package org.jfree.data.category;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.ResourceBundle;
import org.jfree.data.DataUtilities;
import org.jfree.data.UnknownKeyException;
import org.jfree.data.general.AbstractSeriesDataset;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;

public class DefaultIntervalCategoryDataset_setCategoryKeys_TriageGen1Test {

    @Test
    public void testSetCategoryKeys_Success() {
        Comparable[] seriesKeys = {"Series 1"};
        Comparable[] categoryKeys = {"A", "B", "C"};
        Number[][] starts = {{1.0, 2.0, 3.0}};
        Number[][] ends = {{1.5, 2.5, 3.5}};

        DefaultIntervalCategoryDataset dataset = new DefaultIntervalCategoryDataset(seriesKeys, categoryKeys, starts, ends);

        Comparable[] newKeys = {"X", "Y", "Z"};
        dataset.setCategoryKeys(newKeys);

        // Verify via getColumnKey (which typically returns the category keys in JFreeChart)
        // or by checking if the internal state is updated. 
        // Since getColumnKey is available, we use it.
        for (int i = 0; i < newKeys.length; i++) {
            assertEquals(newKeys[i], dataset.getColumnKey(i));
        }
    }








}

