import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;

public class DefaultIntervalCategoryDataset_setCategoryKeys_TriageGen1Test {









    /**
     * Note: The original code contains a bug in the loop condition:
     * for (int i = 0; i <= categoryKeys.length; i++)
     * This will cause an ArrayIndexOutOfBoundsException when i == categoryKeys.length.
     * This test targets that specific branch/line to ensure coverage of the bug.
     */
    @Test(expected = ArrayIndexOutOfBoundsException.class)
    public void testSetCategoryKeys_TriggerIndexOutOfBounds() {
        Comparable[] seriesKeys = {"Series 1"};
        Comparable[] categoryKeys = {"A"};
        Number[][] starts = {{1.0}};
        Number[][] ends = {{2.0}};
        DefaultIntervalCategoryDataset dataset = new DefaultIntervalCategoryDataset(seriesKeys, categoryKeys, starts, ends);

        Comparable[] validKeys = {"X"};
        dataset.setCategoryKeys(validKeys);
    }
}
